for source, values in extras.items():
    for lang, target in values.items():
        translations[lang][source] = target

# These two long descriptions were replaced in ZonePrefs 2.1.0.
for obsolete in (
    "已导入的壁纸(如果遇到设置壁纸不正常右上角注销尝试)",
    "点击切换壁纸，向左滑动可删除不需要的壁纸以及重命名。\n点击对应壁纸旁边的按钮可设置每帧重绘降采样的程度(原画/70%/50%/25%)，以节约电量以及降低占用。",
):
    for values in translations.values():
        values.pop(obsolete, None)

out = Path(__file__).parent
for lang, values in translations.items():
    lines = ['/* ZonePrefs runtime text localization. */']
    for source, target in values.items():
        lines.append(json.dumps(source, ensure_ascii=False) + ' = ' + json.dumps(target, ensure_ascii=False) + ';')
    (out / f'{lang}.lproj' / 'Localizable.strings').write_text('\n'.join(lines) + '\n', encoding='utf-8')
print('Wrote', {k: len(v) for k,v in translations.items()})
